// Initialize sync context and configuration
const input = $input.first().json;
const body = input.body || input;

// Sync configuration
const config = {
  // Sync mode: 'full', 'delta', 'realtime'
  mode: body.mode || 'delta',

  // Conflict resolution: 'source_wins', 'target_wins', 'latest_wins', 'merge', 'manual'
  conflictResolution: body.conflictResolution || 'latest_wins',

  // Source and target configuration
  source: body.source || { type: 'database', name: 'source_db' },
  target: body.target || { type: 'api', name: 'target_api' },

  // Sync options
  batchSize: body.batchSize || 100,
  retryAttempts: body.retryAttempts || 3,
  enableRollback: body.enableRollback !== false,

  // Field mapping
  fieldMapping: body.fieldMapping || null
};

// Initialize sync context
const syncContext = {
  syncId: `sync_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  startedAt: new Date().toISOString(),
  config,
  status: 'initializing',
  stats: {
    processed: 0,
    created: 0,
    updated: 0,
    deleted: 0,
    skipped: 0,
    conflicts: 0,
    errors: 0
  },
  errors: [],
  conflicts: []
};

return [{ json: syncContext }];

// Fetch source data and detect changes
const context = $input.first().json;
const staticData = $workflow.staticData;

// Initialize sync state
if (!staticData.lastSync) {
  staticData.lastSync = {};
}

const sourceName = context.config.source.name;
const lastSyncTime = staticData.lastSync[sourceName] || null;

// Simulated source data fetch (replace with actual data source)
// In production, use HTTP Request node or database node
const simulatedSourceData = [
  { id: '1', name: 'Item 1', updatedAt: new Date().toISOString(), data: { value: 100 } },
  { id: '2', name: 'Item 2', updatedAt: new Date(Date.now() - 3600000).toISOString(), data: { value: 200 } },
  { id: '3', name: 'Item 3', updatedAt: new Date(Date.now() - 7200000).toISOString(), data: { value: 300 } },
  { id: '4', name: 'Item 4 (new)', updatedAt: new Date().toISOString(), data: { value: 400 } }
];

// Filter for delta sync
let sourceRecords = simulatedSourceData;
if (context.config.mode === 'delta' && lastSyncTime) {
  sourceRecords = simulatedSourceData.filter(r => 
    new Date(r.updatedAt) > new Date(lastSyncTime)
  );
}

// Create hash for each record (for change detection)
const crypto = require('crypto');
const recordsWithHash = sourceRecords.map(record => {
  const hash = crypto.createHash('md5')
    .update(JSON.stringify(record.data))
    .digest('hex');
  return { ...record, _hash: hash };
});

return [{
  json: {
    ...context,
    status: 'fetching',
    sourceRecords: recordsWithHash,
    lastSyncTime,
    fetchedAt: new Date().toISOString()
  }
}];

// Fetch target data for comparison
const context = $input.first().json;

// Get IDs to fetch from target
const sourceIds = context.sourceRecords.map(r => r.id);

// Simulated target data fetch (replace with actual target API/database)
const simulatedTargetData = [
  { id: '1', name: 'Item 1', updatedAt: new Date(Date.now() - 1800000).toISOString(), data: { value: 100 }, _hash: 'abc123' },
  { id: '2', name: 'Item 2 (modified)', updatedAt: new Date().toISOString(), data: { value: 250 }, _hash: 'def456' },
  { id: '3', name: 'Item 3', updatedAt: new Date(Date.now() - 7200000).toISOString(), data: { value: 300 }, _hash: 'ghi789' }
];

// Create lookup map
const targetMap = {};
for (const record of simulatedTargetData) {
  targetMap[record.id] = record;
}

return [{
  json: {
    ...context,
    targetRecords: simulatedTargetData,
    targetMap,
    status: 'comparing'
  }
}];

// Detect changes and conflicts
const context = $input.first().json;
const sourceRecords = context.sourceRecords;
const targetMap = context.targetMap;
const conflictResolution = context.config.conflictResolution;

const changes = {
  create: [],
  update: [],
  conflict: [],
  skip: []
};

for (const sourceRecord of sourceRecords) {
  const targetRecord = targetMap[sourceRecord.id];

  if (!targetRecord) {
    // New record - create
    changes.create.push({
      action: 'create',
      record: sourceRecord,
      reason: 'not_in_target'
    });
  } else if (sourceRecord._hash === targetRecord._hash) {
    // No change - skip
    changes.skip.push({
      action: 'skip',
      record: sourceRecord,
      reason: 'no_change'
    });
  } else {
    // Different - check for conflict
    const sourceTime = new Date(sourceRecord.updatedAt).getTime();
    const targetTime = new Date(targetRecord.updatedAt).getTime();

    if (sourceTime > targetTime) {
      // Source is newer - update
      changes.update.push({
        action: 'update',
        record: sourceRecord,
        previousRecord: targetRecord,
        reason: 'source_newer'
      });
    } else if (sourceTime < targetTime) {
      // Target is newer - potential conflict
      if (conflictResolution === 'source_wins') {
        changes.update.push({
          action: 'update',
          record: sourceRecord,
          previousRecord: targetRecord,
          reason: 'source_wins_policy'
        });
      } else if (conflictResolution === 'target_wins') {
        changes.skip.push({
          action: 'skip',
          record: sourceRecord,
          reason: 'target_wins_policy'
        });
      } else if (conflictResolution === 'latest_wins') {
        changes.skip.push({
          action: 'skip',
          record: sourceRecord,
          reason: 'target_is_latest'
        });
      } else {
        // Manual resolution needed
        changes.conflict.push({
          action: 'conflict',
          sourceRecord,
          targetRecord,
          reason: 'manual_resolution_required'
        });
      }
    } else {
      // Same timestamp but different content - merge conflict
      changes.conflict.push({
        action: 'conflict',
        sourceRecord,
        targetRecord,
        reason: 'concurrent_modification'
      });
    }
  }
}

return [{
  json: {
    ...context,
    changes,
    status: 'processing',
    changesSummary: {
      toCreate: changes.create.length,
      toUpdate: changes.update.length,
      conflicts: changes.conflict.length,
      toSkip: changes.skip.length
    }
  }
}];

// Create rollback snapshot before applying changes
const context = $input.first().json;
const staticData = $workflow.staticData;

if (context.config.enableRollback) {
  // Store rollback data
  if (!staticData.rollbackSnapshots) {
    staticData.rollbackSnapshots = [];
  }

  const snapshot = {
    syncId: context.syncId,
    createdAt: new Date().toISOString(),
    changes: context.changes,
    targetSnapshot: context.targetRecords
  };

  staticData.rollbackSnapshots.push(snapshot);

  // Keep only last 10 snapshots
  if (staticData.rollbackSnapshots.length > 10) {
    staticData.rollbackSnapshots = staticData.rollbackSnapshots.slice(-10);
  }

  return [{
    json: {
      ...context,
      rollbackEnabled: true,
      snapshotId: context.syncId
    }
  }];
}

return [{ json: { ...context, rollbackEnabled: false } }];

// Apply changes to target
const context = $input.first().json;
const changes = context.changes;
const stats = { ...context.stats };
const errors = [];

// Process creates
for (const item of changes.create) {
  try {
    // Simulated create (replace with actual API/database call)
    console.log(`Creating: ${item.record.id}`);
    stats.created++;
    stats.processed++;
  } catch (error) {
    errors.push({ action: 'create', record: item.record, error: error.message });
    stats.errors++;
  }
}

// Process updates
for (const item of changes.update) {
  try {
    // Simulated update (replace with actual API/database call)
    console.log(`Updating: ${item.record.id}`);
    stats.updated++;
    stats.processed++;
  } catch (error) {
    errors.push({ action: 'update', record: item.record, error: error.message });
    stats.errors++;
  }
}

// Track skipped
stats.skipped = changes.skip.length;
stats.conflicts = changes.conflict.length;

return [{
  json: {
    ...context,
    stats,
    errors,
    conflicts: changes.conflict,
    status: 'verifying'
  }
}];

// Verify sync and compile report
const context = $input.first().json;
const staticData = $workflow.staticData;

// Update last sync time
const sourceName = context.config.source.name;
staticData.lastSync = staticData.lastSync || {};
staticData.lastSync[sourceName] = new Date().toISOString();

// Determine final status
let status = 'completed';
if (context.stats.errors > 0) {
  status = context.stats.processed > 0 ? 'partial' : 'failed';
} else if (context.stats.conflicts > 0) {
  status = 'completed_with_conflicts';
}

const report = {
  syncId: context.syncId,
  status,
  mode: context.config.mode,
  source: context.config.source.name,
  target: context.config.target.name,

  timing: {
    startedAt: context.startedAt,
    completedAt: new Date().toISOString(),
    durationMs: Date.now() - new Date(context.startedAt).getTime()
  },

  stats: context.stats,

  rollback: context.rollbackEnabled ? {
    available: true,
    snapshotId: context.snapshotId,
    expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
  } : { available: false },

  errors: context.errors.length > 0 ? context.errors : null,
  conflicts: context.conflicts.length > 0 ? context.conflicts : null
};

return [{ json: report }];
